/**
 * Single-module utility package modeling the CVE class "vulnerability
 * localized to one exported API" (shape of lodash `template`,
 * CVE-2021-23337: options.sourceURL is interpolated into Function source
 * without sanitization -> arbitrary code injection for attacker-controlled
 * options). The package must remain deployed (escape/merge are used); the
 * vulnerable API is unused and should be physically removed.
 */

const htmlEscapes = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(string) {
  const s = String(string == null ? '' : string);
  return /[&<>"']/.test(s) ? s.replace(/[&<>"']/g, (ch) => htmlEscapes[ch]) : s;
}

export function merge(target, ...sources) {
  for (const source of sources) {
    if (source == null) continue;
    for (const key of Object.keys(source)) {
      const sv = source[key];
      const tv = target[key];
      if (sv && typeof sv === 'object' && !Array.isArray(sv) && tv && typeof tv === 'object' && !Array.isArray(tv)) {
        merge(tv, sv);
      } else if (Array.isArray(sv)) {
        target[key] = Array.isArray(tv) ? tv.concat(sv) : sv.slice();
      } else if (sv !== undefined) {
        target[key] = sv;
      }
    }
  }
  return target;
}

